import java.util.*;

public class Main {
    public static void main(String[] args) throws Exception {
        FastReader r = new FastReader();
        int n = r.nextInt();
        long[] lender = new long[n], payback = new long[n];
        for (int i = 0; i < n; i++) lender[i] = r.nextLong();
        for (int i = 0; i < n; i++) payback[i] = r.nextLong();
        long[] values = Arrays.stream(payback).sorted().distinct().toArray();
        int[] debts = new int[n], limits = new int[n];
        for (int j = 0; j < n; j++) {
            debts[j] = Arrays.binarySearch(values, payback[j]) + 1;
            int lo = 0, hi = values.length; // count of values <= lender[j]
            while (lo < hi) { int mid = (lo + hi) >>> 1; if (values[mid] <= lender[j]) lo = mid + 1; else hi = mid; }
            limits[j] = lo;
        }
        int unreachable = values.length + 1;
        // best[mask]: smallest rank of the final payback over orders of exactly the lenders in mask.
        byte[] best = new byte[1 << n];
        Arrays.fill(best, (byte) unreachable);
        best[0] = 0;
        int ans = 0;
        for (int mask = 1; mask < (1 << n); mask++) {
            int bits = mask, debt = unreachable;
            while (bits != 0) {
                int bit = bits & -bits;
                int j = Integer.numberOfTrailingZeros(bit);
                bits ^= bit;
                if (best[mask ^ bit] <= limits[j] && debts[j] < debt) debt = debts[j];
            }
            best[mask] = (byte) debt;
            if (debt != unreachable) ans = Math.max(ans, Integer.bitCount(mask));
        }
        System.out.println(ans);
    }
}

final class FastReader {
    private final java.io.InputStream in = System.in;
    private final byte[] buf = new byte[1 << 16];
    private int len = 0, ptr = 0;

    private int read() throws java.io.IOException {
        if (ptr == len) {
            len = in.read(buf, 0, buf.length);
            ptr = 0;
            if (len <= 0) { len = 0; return -1; }
        }
        return buf[ptr++];
    }

    String next() throws java.io.IOException {
        int c = read();
        while (c != -1 && c <= ' ') c = read();
        StringBuilder sb = new StringBuilder();
        while (c > ' ') { sb.append((char) c); c = read(); }
        return sb.toString();
    }

    long nextLong() throws java.io.IOException {
        int c = read();
        while (c != -1 && c <= ' ') c = read();
        boolean neg = c == '-';
        if (neg) c = read();
        long r = 0;
        while (c >= '0' && c <= '9') { r = r * 10 + (c - '0'); c = read(); }
        return neg ? -r : r;
    }

    int nextInt() throws java.io.IOException { return (int) nextLong(); }
}

