	"sort"
)

func main() {
	n := readInt()
	lender := make([]int, n)
	payback := make([]int, n)
	for i := range lender {
		lender[i] = readInt()
	}
	for i := range payback {
		payback[i] = readInt()
	}
	values := slices.Clone(payback)
	slices.Sort(values)
	values = slices.Compact(values)
	debts := make([]int, n)
	limits := make([]int, n)
	for j := 0; j < n; j++ {
		debts[j] = sort.SearchInts(values, payback[j]) + 1
		limits[j] = sort.SearchInts(values, lender[j]+1) // count of values <= lender[j]
	}
	unreachable := len(values) + 1
	// best[mask]: smallest rank of the final payback over orders of exactly the lenders in mask.
	best := make([]uint8, 1<<n)
	for i := range best {
		best[i] = uint8(unreachable)
	}
	best[0] = 0
	ans := 0
	for mask := uint32(1); mask < 1<<n; mask++ {
		rest := mask
		debt := unreachable
		for rest != 0 {
			j := bits.TrailingZeros32(rest)
			bit := rest & -rest
			rest ^= bit
			if int(best[mask^bit]) <= limits[j] && debts[j] < debt {
				debt = debts[j]
			}
		}
		best[mask] = uint8(debt)
		if debt != unreachable {
			ans = max(ans, bits.OnesCount32(mask))
		}
	}
	fmt.Println(ans)
}

var reader = bufio.NewReaderSize(os.Stdin, 1<<16)

func readToken() string {
	b, err := reader.ReadByte()
	for err == nil && b <= ' ' {
		b, err = reader.ReadByte()
	}
	var buf []byte
	for err == nil && b > ' ' {
		buf = append(buf, b)
		b, err = reader.ReadByte()
	}
	return string(buf)
}

func readInt() int {
	b, err := reader.ReadByte()
	for err == nil && b <= ' ' {
		b, err = reader.ReadByte()
	}
	neg := false
	if b == '-' {
		neg = true
		b, err = reader.ReadByte()
	}
	r := 0
	for err == nil && b >= '0' && b <= '9' {
		r = r*10 + int(b-'0')
		b, err = reader.ReadByte()
	}
	if neg {
		return -r
	}
	return r
}
